:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c5ce7;
  --accent-hover: #7d6ef0;
  --accent-active: #5a4bd1;
  --swatch-radius: 12px;
  --focus-ring: 0 0 0 3px #a29bfe;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  letter-spacing: -0.02em;
}

.subtitle {
  text-align: center;
  font-size: 1rem;
  color: #b0b0c8;
  margin-top: -8px;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.color-block {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: var(--swatch-radius);
  border: 2px solid rgba(255, 255, 255, 0.1);
  transition: transform 0.15s ease, border-color 0.15s ease;
}

.color-block:hover {
  transform: scale(1.03);
  border-color: rgba(255, 255, 255, 0.3);
}

.hex-code {
  font-size: 0.8rem;
  font-family: 'SF Mono', 'Fira Code', monospace;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #d0d0e0;
  text-align: center;
  word-break: break-all;
}

.lock-btn {
  background: transparent;
  border: 1px solid #555;
  border-radius: 8px;
  color: #b0b0c8;
  font-size: 0.9rem;
  padding: 4px 8px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  min-width: 44px;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lock-btn:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  border-color: #888;
}

.lock-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
}

.lock-btn[aria-pressed="true"]:active {
  background: var(--accent-active);
}

.generate-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 12px;
  padding: 14px 24px;
  font-size: 1.125rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  width: 100%;
  min-height: 52px;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.generate-btn:active {
  background: var(--accent-active);
  transform: scale(0.98);
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
    border-radius: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .palette {
    gap: 6px;
  }
  .hex-code {
    font-size: 0.7rem;
  }
  .lock-btn {
    font-size: 0.8rem;
    min-width: 36px;
    min-height: 36px;
    padding: 2px 4px;
  }
}

@media (max-width: 360px) {
  .palette {
    grid-template-columns: repeat(5, 1fr);
    gap: 4px;
  }
  .hex-code {
    font-size: 0.65rem;
  }
  .lock-btn {
    font-size: 0.7rem;
    min-width: 32px;
    min-height: 32px;
  }
}

(function () {
  'use strict';

  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate');

  const SWATCH_COUNT = 5;
  let locked = new Array(SWATCH_COUNT).fill(false);
  let colors = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  }

  function generateHarmoniousPalette() {
    const baseHue = Math.random() * 360;
    const schemes = [
      [0, 30, 60, 180, 240],
      [0, 40, 80, 160, 200],
      [0, 120, 240, 60, 180],
      [0, 20, 180, 200, 300],
      [0, 60, 180, 240, 300],
    ];
    const offsets = schemes[Math.floor(Math.random() * schemes.length)];
    const sat = 60 + Math.random() * 20;
    const lightBase = 45 + Math.random() * 15;

    return offsets.map((offset, i) => {
      const hue = (baseHue + offset) % 360;
      const lightness = lightBase + (i % 2 === 0 ? 5 : -5);
      return hslToHex(hue, sat, lightness);
    });
  }

  function render() {
    paletteEl.innerHTML = '';
    colors.forEach((hex, i) => {
      const swatch = document.createElement('div');
      swatch.className = 'swatch';

      const block = document.createElement('div');
      block.className = 'color-block';
      block.style.backgroundColor = hex;
      block.setAttribute('aria-hidden', 'true');

      const hexLabel = document.createElement('span');
      hexLabel.className = 'hex-code';
      hexLabel.textContent = hex;

      const lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.textContent = locked[i] ? '\uD83D\uDD12' : '\uD83D\uDD13';
      lockBtn.setAttribute('aria-pressed', locked[i] ? 'true' : 'false');
      lockBtn.setAttribute('aria-label', `Lock color ${hex}`);
      lockBtn.addEventListener('click', () => toggleLock(i));

      swatch.appendChild(block);
      swatch.appendChild(hexLabel);
      swatch.appendChild(lockBtn);
      paletteEl.appendChild(swatch);
    });
  }

  function toggleLock(index) {
    locked[index] = !locked[index];
    render();
  }

  function generate() {
    const newPalette = generateHarmoniousPalette();
    colors = colors.length === 0
      ? newPalette
      : newPalette.map((hex, i) => (locked[i] ? colors[i] : hex));
    render();
  }

  generateBtn.addEventListener('click', generate);

  // Initialize
  colors = generateHarmoniousPalette();
  render();
})();
